//! 📥️ Bounded native pages initialize one canonical arena destination under the original exclusive receiving grant.
use super::*;
use std::mem::ManuallyDrop;
pub const MESH3D_RESOURCE_COMPONENT_COUNT_CAPACITY:usize=600000;
const FIELDS:[Mesh3dField;14]=[Mesh3dField::Positions,Mesh3dField::Normals,Mesh3dField::Indices,Mesh3dField::FaceIds,Mesh3dField::VertexIds,Mesh3dField::Edges,Mesh3dField::EdgeIds,Mesh3dField::Uvs,Mesh3dField::Colors,Mesh3dField::UvsMetallicRoughness,Mesh3dField::UvsNormal,Mesh3dField::UvsOcclusion,Mesh3dField::UvsEmissive,Mesh3dField::Tangents];
type Labels=Vec<(String,Vec<String>)>;
type Scratch=(Labels,Option<Vec<u8>>);
