pub struct Mesh3dReceivingStep{pub consumed_bytes:usize,pub progress:RetainedCloneProgress}
pub struct Mesh3dResourceReceiving{identity:Mesh3dResourceIdentity,schema:Mesh3dSchema,counts:[usize;3],token:Option<Mesh3dWriteToken>,lease:Option<Mesh3dLease>,owner:ManuallyDrop<Option<Mesh3dResourceOwner>>,labels:ManuallyDrop<Labels>,label:ManuallyDrop<Option<Vec<u8>>>,scratch_close:ManuallyDrop<Option<ControlledRetirement<Scratch>>>,field:usize,item:u32,geometry:usize,record:[u8;24],record_length:usize,domain:usize,group:usize,label_extent:usize,label_offset:usize,utf8_expected:u8,utf8_lower:u8,utf8_upper:u8,directory:usize,phase:u8,aborting:bool,closing:bool,closed:bool}
fn metadata(grant:RetainedCloneGrant)->bool{grant.maximum_items!=0&&grant.maximum_depth!=0}
fn posted()->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,..Default::default()}}
fn fits(grant:RetainedCloneGrant,demand:RetirementDemand)->bool{metadata(grant)&&grant.maximum_copy_bytes>=demand.copy_bytes&&grant.maximum_capacity_bytes>=demand.capacity_bytes&&grant.maximum_release_bytes>=demand.release_bytes&&grant.maximum_depth>=demand.depth}
impl Mesh3dResourceReceiving{
 pub fn admit(identity:Mesh3dResourceIdentity,schema:Mesh3dSchema,counts:[usize;3],geometry_bytes:usize,grant:RetainedCloneGrant)->Result<Option<(Self,RetainedCloneProgress)>,Mesh3dFault>{if identity.operation==0||identity.generation==0||identity.cache_epoch==0||counts.iter().any(|count|*count>MESH3D_RESOURCE_COMPONENT_COUNT_CAPACITY)||schema.layout()?.total_bytes!=geometry_bytes{return Err(Mesh3dFault::Schema)}if !metadata(grant){return Ok(None)}Ok(Some((Self{identity,schema,counts,token:None,lease:None,owner:ManuallyDrop::new(None),labels:ManuallyDrop::new(Vec::new()),label:ManuallyDrop::new(None),scratch_close:ManuallyDrop::new(None),field:0,item:0,geometry:0,record:[0;24],record_length:0,domain:0,group:0,label_extent:0,label_offset:0,utf8_expected:0,utf8_lower:0x80,utf8_upper:0xbf,directory:0,phase:0,aborting:false,closing:false,closed:false},posted()))) }
 pub fn geometry_write_pending(&self)->bool{self.phase==2&&self.field<FIELDS.len()&&self.record_length==Mesh3dSchema::field_item_bytes(FIELDS[self.field])}
 pub fn geometry_offset(&self)->usize{self.geometry}
 pub fn label_frontier(&self)->Option<(usize,usize,usize)>{(!self.closing&&self.phase==4&&self.domain<3).then_some((self.domain,self.group,self.label_offset))}
 pub fn is_ready(&self)->bool{self.phase==9&&!self.closing&&self.owner.is_some()}
 pub fn advance(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneProgress,Mesh3dFault>{if self.closing||self.closed||!metadata(grant){return Ok(Default::default())}match self.phase{
  0=>{if grant.maximum_capacity_bytes<mesh3d_begin_capacity_byte_demand(){return Ok(Default::default())}let(token,progress)=mesh3d_begin(self.identity.generation,self.identity.revision,self.schema,grant)?;self.token=Some(token);self.phase=1;Ok(progress)},
  1=>{let token=self.token.unwrap();if grant.maximum_capacity_bytes<mesh3d_allocate_capacity_byte_demand(token)?{return Ok(Default::default())}let step=mesh3d_allocate_step(token,grant)?;if step.complete{self.phase=2}Ok(step.progress)},
  2=>{if self.field==FIELDS.len(){self.phase=if self.counts==[0;3]{7}else{3};return Ok(posted())}let field=FIELDS[self.field];if self.item==self.schema.field_items(field){self.field+=1;self.item=0;return Ok(posted())}Ok(Default::default())},
  3=>self.directory_step(grant),
  4=>{if self.domain==3{self.phase=5;return Ok(posted())}if self.group==self.counts[self.domain]{self.domain+=1;self.group=0;return Ok(posted())}Ok(Default::default())},
  5=>{let token=self.token.unwrap();let table=ComponentReferenceTable::from_entries(std::mem::take(&mut*self.labels));let demand=match mesh3d_component_capacity_byte_demand(&table){Ok(demand)=>demand,Err(failure)=>{*self.labels=table.into_entries();return Err(failure)}};if grant.maximum_capacity_bytes<demand{*self.labels=table.into_entries();return Ok(Default::default())}let mut table=table;let result=mesh3d_move_component_references(token,&mut table,grant);if !table.is_empty(){*self.labels=table.into_entries()}let progress=result?;self.phase=6;Ok(progress)},
  6=>{let step=mesh3d_component_admission_step(self.token.unwrap(),RetainedCloneGrant{maximum_items:1,..grant})?;if step.complete{self.phase=7}Ok(step.ownership)},
  7=>{self.lease=Some(mesh3d_seal(self.token.unwrap())?);self.token=None;self.phase=8;Ok(posted())},
  8=>{let Some((owner,progress))=Mesh3dResourceOwner::admit(&mut self.lease,self.identity,grant)?else{return Ok(Default::default())};*self.owner=Some(owner);self.phase=9;Ok(progress)},
  9=>Ok(Default::default()),_=>Err(Mesh3dFault::Order)}}
 fn directory_step(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneProgress,Mesh3dFault>{if self.labels.capacity()==0{let bytes=3*size_of::<(String,Vec<String>)>();if grant.maximum_capacity_bytes<bytes{return Ok(Default::default())}self.labels.try_reserve_exact(3).map_err(|_|Mesh3dFault::ByteCapacity)?;return Ok(RetainedCloneProgress{retained_capacity_bytes:self.labels.capacity()*size_of::<(String,Vec<String>)>(),..posted()})}if self.directory==3{self.phase=4;return Ok(posted())}if self.labels.len()==self.directory{let name=["face","edge","vertex"][self.directory];if grant.maximum_copy_bytes<name.len()||grant.maximum_capacity_bytes<name.len(){return Ok(Default::default())}let mut key=String::new();key.try_reserve_exact(name.len()).map_err(|_|Mesh3dFault::ByteCapacity)?;key.push_str(name);let capacity=key.capacity();self.labels.push((key,Vec::new()));return Ok(RetainedCloneProgress{copied_bytes:name.len(),retained_capacity_bytes:capacity,..posted()})}let labels=&mut self.labels[self.directory].1;let count=self.counts[self.directory];let bytes=count.checked_mul(size_of::<String>()).ok_or(Mesh3dFault::ByteCapacity)?;if grant.maximum_capacity_bytes<bytes{return Ok(Default::default())}labels.try_reserve_exact(count).map_err(|_|Mesh3dFault::ByteCapacity)?;self.directory+=1;Ok(RetainedCloneProgress{retained_capacity_bytes:labels.capacity()*size_of::<String>(),..posted()})}
 pub fn receive_geometry(&mut self,offset:usize,bytes:&[u8],grant:RetainedCloneGrant)->Result<Mesh3dReceivingStep,Mesh3dFault>{if self.closing||self.phase!=2||offset!=self.geometry||self.field==FIELDS.len(){return Err(Mesh3dFault::Order)}if !metadata(grant){return Ok(Default::default())}let field=FIELDS[self.field];if self.item==self.schema.field_items(field){return Ok(Default::default())}let length=Mesh3dSchema::field_item_bytes(field);if self.record_length==length{if grant.maximum_copy_bytes<length{return Ok(Default::default())}let token=self.token.unwrap();let word=|index:usize|u32::from_le_bytes(self.record[index*4..index*4+4].try_into().unwrap());let float=|index|f32::from_bits(word(index));match field{Mesh3dField::Positions|Mesh3dField::Normals=>mesh3d_write_vec3(token,field,[float(0),float(1),float(2)])?,Mesh3dField::Edges=>mesh3d_write_edge(token,[[float(0),float(1),float(2)],[float(3),float(4),float(5)]])?,Mesh3dField::Uvs|Mesh3dField::UvsMetallicRoughness|Mesh3dField::UvsNormal|Mesh3dField::UvsOcclusion|Mesh3dField::UvsEmissive=>mesh3d_write_vec2(token,field,[float(0),float(1)])?,Mesh3dField::Colors|Mesh3dField::Tangents=>mesh3d_write_vec4(token,field,[float(0),float(1),float(2),float(3)])?,_=>mesh3d_write_u32(token,field,word(0))?}self.item+=1;self.record_length=0;return Ok(Mesh3dReceivingStep{consumed_bytes:0,progress:RetainedCloneProgress{copied_bytes:length,..posted()}})}let count=bytes.len().min(64).min(length-self.record_length).min(grant.maximum_copy_bytes);if count==0{return Ok(Default::default())}self.record[self.record_length..self.record_length+count].copy_from_slice(&bytes[..count]);self.record_length+=count;self.geometry+=count;Ok(Mesh3dReceivingStep{consumed_bytes:count,progress:RetainedCloneProgress{copied_bytes:count,..posted()}})}
 /// 🔤️ Each bounded source window validates UTF-8 before its bytes enter the owned label; completed validation justifies the zero-copy string transfer.
 pub fn receive_label(&mut self,domain:usize,group:usize,offset:usize,extent:usize,bytes:&[u8],grant:RetainedCloneGrant)->Result<Mesh3dReceivingStep,Mesh3dFault>{if self.closing||self.phase!=4||domain!=self.domain||group!=self.group||domain>=3||group>=self.counts[domain]||offset!=self.label_offset||extent>MESH3D_OWNER_BYTE_CAPACITY{return Err(Mesh3dFault::Order)}if !metadata(grant){return Ok(Default::default())}if self.label.is_none(){if grant.maximum_capacity_bytes<extent{return Ok(Default::default())}let mut label=Vec::new();label.try_reserve_exact(extent).map_err(|_|Mesh3dFault::ByteCapacity)?;let capacity=label.capacity();*self.label=Some(label);self.label_extent=extent;return Ok(Mesh3dReceivingStep{progress:RetainedCloneProgress{retained_capacity_bytes:capacity,..posted()},..Default::default()})}if extent!=self.label_extent{return Err(Mesh3dFault::Schema)}if offset==extent{if self.utf8_expected!=0{return Err(Mesh3dFault::Schema)}let bytes=self.label.take().unwrap();let label=unsafe{String::from_utf8_unchecked(bytes)};self.labels[domain].1.push(label);self.group+=1;self.label_extent=0;self.label_offset=0;return Ok(Mesh3dReceivingStep{progress:posted(),..Default::default()})}let count=bytes.len().min(64).min(extent-offset).min(grant.maximum_copy_bytes);if count==0{return Ok(Default::default())}let state=(self.utf8_expected,self.utf8_lower,self.utf8_upper);for byte in &bytes[..count]{if let Err(failure)=self.validate_utf8(*byte){(self.utf8_expected,self.utf8_lower,self.utf8_upper)=state;return Err(failure)}}self.label.as_mut().unwrap().extend_from_slice(&bytes[..count]);self.label_offset+=count;Ok(Mesh3dReceivingStep{consumed_bytes:count,progress:RetainedCloneProgress{copied_bytes:count,..posted()}})}
 fn validate_utf8(&mut self,byte:u8)->Result<(),Mesh3dFault>{if self.utf8_expected!=0{if byte<self.utf8_lower||byte>self.utf8_upper{return Err(Mesh3dFault::Schema)}self.utf8_expected-=1;self.utf8_lower=0x80;self.utf8_upper=0xbf;return Ok(())}let(expected,lower,upper)=match byte{0..=0x7f=>return Ok(()),0xc2..=0xdf=>(1,0x80,0xbf),0xe0=>(2,0xa0,0xbf),0xe1..=0xec|0xee..=0xef=>(2,0x80,0xbf),0xed=>(2,0x80,0x9f),0xf0=>(3,0x90,0xbf),0xf1..=0xf3=>(3,0x80,0xbf),0xf4=>(3,0x80,0x8f),_=>(0,0,0)};if expected==0{return Err(Mesh3dFault::Schema)}self.utf8_expected=expected;self.utf8_lower=lower;self.utf8_upper=upper;Ok(())}
 pub fn take_ready(&mut self,grant:RetainedCloneGrant)->Option<(Mesh3dResourceOwner,RetainedCloneProgress)>{if !self.is_ready()||!metadata(grant){return None}self.closed=true;Some((self.owner.take().unwrap(),posted()))}
 pub fn close_step(&mut self,grant:RetainedCloneGrant)->Result<Mesh3dOwnershipStep,Mesh3dFault>{if self.closed{return Ok(Mesh3dOwnershipStep{complete:true,..Default::default()})}if !metadata(grant){return Ok(Default::default())}self.closing=true;if let Some(owner)=self.owner.as_mut(){let demand=owner.close_demands(grant.maximum_copy_bytes)?;if !fits(grant,demand){return Ok(Default::default())}let mut step=owner.close_step(grant)?;if step.complete{self.owner.take();}step.complete=false;return Ok(step)}if let Some(token)=self.token{if !self.aborting{mesh3d_abort(token)?;self.aborting=true;return Ok(Mesh3dOwnershipStep{progress:posted(),..Default::default()})}let demand=mesh3d_abort_demands(token,grant.maximum_copy_bytes)?;if !fits(grant,demand){return Ok(Default::default())}let mut step=mesh3d_abort_step(token,grant)?;if step.complete{self.token=None}step.complete=false;return Ok(step)}if let Some(lease)=self.lease{if !self.aborting{mesh3d_begin_close(lease)?;self.aborting=true;return Ok(Mesh3dOwnershipStep{progress:posted(),..Default::default()})}let demand=mesh3d_close_demands(lease,grant.maximum_copy_bytes)?;if !fits(grant,demand){return Ok(Default::default())}let mut step=mesh3d_close_step(lease,grant)?;if step.complete{self.lease=None}step.complete=false;return Ok(step)}if let Some(owner)=self.scratch_close.as_mut(){if !owner.terminal_is_empty(){let demand=controlled_demands(owner,grant.maximum_copy_bytes)?;if !fits(grant,demand){return Ok(Default::default())}let step=owner.step(RetainedCloneGrant{maximum_items:1,..grant}).map_err(|_|Mesh3dFault::Closing)?;return Ok(Mesh3dOwnershipStep{progress:step.progress(),..Default::default()})}self.scratch_close.take();return Ok(Mesh3dOwnershipStep{progress:posted(),..Default::default()})}if self.labels.capacity()!=0||self.label.is_some(){let source=(std::mem::take(&mut*self.labels),self.label.take());match ControlledRetirement::new(source){Ok(owner)=>*self.scratch_close=Some(owner),Err((_,(labels,label)))=>{*self.labels=labels;*self.label=label;return Err(Mesh3dFault::Closing)}}return Ok(Mesh3dOwnershipStep{progress:posted(),..Default::default()})}self.closed=true;Ok(Mesh3dOwnershipStep{complete:true,progress:posted()})}
 pub fn terminal_is_empty(&self)->bool{self.closed&&self.token.is_none()&&self.lease.is_none()&&self.owner.is_none()&&self.labels.capacity()==0&&self.label.is_none()&&self.scratch_close.is_none()}
}
impl Drop for Mesh3dResourceReceiving{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native mesh receiver dropped before original paid source and destination close")}}
